INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('442b1b62-1efd-4442-85a4-6e924d8f02af', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["Simple"], "source": "DeepSeek AI", "cook_time": "15 mins", "nutrition": "Calories: 450, Protein: 30g, Carbs: 60g, Fat: 10g", "prep_time": "10 mins", "difficulty": "Easy", "total_time": "25 mins", "ingredients": ["2 fish fillets, cubed", "1.5 cups cooked rice", "3 green onions, chopped (separate white and green parts)", "1 tbsp cooking oil*", "1/2 tsp salt", "1/4 tsp garlic powder*"], "recipe_name": "Green Onion Fish Rice Bowl", "ai_generated": true, "allergy_safe": true, "instructions": ["Heat oil in a non-stick skillet over medium-high heat.", "Add the cubed fish and the white parts of the green onions. Season with salt and garlic powder. Cook for 4-5 minutes, stirring occasionally, until fish is cooked through.", "Add the cooked rice to the skillet. Stir-fry for 2-3 minutes until heated through.", "Remove from heat, stir in the green parts of the onions, and serve immediately."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["garlic powder"], "missing_ingredients_count": 1}, "dinner": {"tags": ["Normal"], "source": "DeepSeek AI", "cook_time": "20 mins", "nutrition": "Calories: 520, Protein: 38g, Carbs: 65g, Fat: 14g", "prep_time": "15 mins", "difficulty": "Medium", "total_time": "35 mins", "ingredients": ["2 fish fillets (like cod or salmon)", "1 cup jasmine rice", "4 green onions (2 minced, 2 sliced for garnish)", "3 tbsp soy sauce*", "1 tbsp honey* or maple syrup*", "1 tbsp fresh ginger, grated*", "2 cloves garlic, minced*", "1 tbsp sesame oil*", "1 cup water", "1 tbsp cooking oil*"], "recipe_name": "Ginger-Soy Glazed Fish with Green Onion Rice", "ai_generated": true, "allergy_safe": true, "instructions": ["Cook rice according to package instructions, using 1 cup water. Once cooked, fluff with a fork and stir in the sliced green onions. Cover to keep warm.", "In a small bowl, whisk together soy sauce, honey, grated ginger, minced garlic, and sesame oil to make the glaze.", "Pat fish fillets dry. Heat cooking oil in a non-stick skillet over medium heat.", "Place fish in the skillet, skin-side down if applicable. Cook for 4-5 minutes.", "Flip the fish carefully. Pour the glaze over and around the fish. Cook for another 3-4 minutes, basting occasionally, until fish is cooked through and glaze has thickened slightly.", "Serve the glazed fish over the green onion rice, spooning any extra glaze from the pan on top."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["soy sauce", "honey or maple syrup", "fresh ginger, grated", "garlic, minced", "sesame oil"], "missing_ingredients_count": 5}, "snacks": [{"name": "Greek Yogurt with Berries", "calories": 150}, {"name": "Handful of Almonds", "calories": 100}], "breakfast": {"tags": ["Simple"], "source": "DeepSeek AI", "cook_time": "20 mins", "nutrition": "Calories: 320, Protein: 28g, Carbs: 40g, Fat: 4g", "prep_time": "10 mins", "difficulty": "Easy", "total_time": "30 mins", "ingredients": ["1 lb white fish fillets, cut into chunks", "1/2 cup white rice", "4 green onions, chopped (separate white and green parts)", "4 cups water or light broth*", "1 inch ginger, sliced*", "1 tsp salt", "1/2 tsp white pepper*"], "recipe_name": "Simple Fish & Scallion Soup with Rice", "ai_generated": true, "allergy_safe": true, "instructions": ["Rinse the rice. In a medium pot, bring water/broth, rice, the white parts of the green onions, and ginger slices to a boil.", "Reduce heat to low, cover, and simmer for 15 minutes, until rice is tender.", "Gently add the fish chunks to the simmering soup. Season with salt and white pepper.", "Cook for 3-5 minutes, until the fish is just cooked through and opaque. Do not stir vigorously.", "Remove from heat. Discard ginger slices if desired. Stir in the green parts of the onions. Adjust seasoning and serve hot."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["water or light broth", "ginger, sliced", "white pepper"], "missing_ingredients_count": 3}}, "total_calories": 1850, "nutrition_summary": "High protein, moderate carb, rich in omega-3 fatty acids and antioxidants. The plan uses three distinct fish and rice recipes to provide variety while maintaining a balanced macronutrient profile. Snacks are added to meet the calorie target and provide additional nutrients."}', '2025-12-25T06:15:37.840003+00:00');
INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('1f3bd557-cb3b-4ff6-8758-c1131855db71', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["Simple"], "source": "DeepSeek AI", "cook_time": "15 mins", "nutrition": "Calories: 480, Protein: 40g, Carbs: 50g, Fat: 12g", "prep_time": "10 mins", "difficulty": "Easy", "total_time": "25 mins", "ingredients": ["2 fish fillets (~6oz each), cut into bite-sized pieces", "1.5 cups cooked rice (leftover works best)", "3 green onions, chopped (separate white and green parts)", "1 tbsp cooking oil*", "1 tbsp soy sauce* (use tamari for gluten-free)", "1/2 tsp sesame oil*"], "recipe_name": "Green Onion Fish Rice Bowl", "ai_generated": true, "allergy_safe": true, "instructions": ["Heat cooking oil in a large skillet or wok over medium-high heat.", "Add the fish pieces and the white parts of the green onions. Cook for 4-5 minutes, stirring occasionally, until fish is cooked through and opaque.", "Add the cooked rice to the skillet. Break up any clumps and stir-fry for 3-4 minutes until heated through.", "Drizzle the soy sauce and sesame oil over the rice and fish. Toss everything to combine evenly.", "Remove from heat and stir in the green parts of the onions. Taste and adjust seasoning if needed. Serve hot."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["soy sauce (use tamari for gluten-free)", "sesame oil"], "missing_ingredients_count": 2}, "dinner": {"tags": ["Simple"], "source": "DeepSeek AI", "cook_time": "25 mins", "nutrition": "Calories: 460, Protein: 39g, Carbs: 58g, Fat: 9g", "prep_time": "15 mins", "difficulty": "Easy", "total_time": "40 mins", "ingredients": ["2 fish fillets (~6oz each)", "3/4 cup white rice", "2 green onions, finely chopped", "1 lemon* (zest and juice)", "2 cloves garlic*, minced", "1 tbsp olive oil*", "1.5 cups chicken or vegetable broth*", "1 tsp dried dill* or parsley*", "Salt and pepper to taste"], "recipe_name": "Lemon-Herb Baked Fish with Rice Pilaf", "ai_generated": true, "allergy_safe": true, "instructions": ["Preheat oven to 400\u00b0F (200\u00b0C).", "In an oven-safe skillet, heat olive oil over medium heat. Add rice and cook for 2 minutes until lightly toasted.", "Add minced garlic and the white parts of the green onions. Cook for 1 minute until fragrant.", "Pour in the broth, lemon zest, and half the lemon juice. Bring to a simmer.", "Nestle the fish fillets into the rice. Season fish with salt, pepper, and dried dill.", "Cover the skillet tightly with foil or a lid and bake for 20-25 minutes, until rice is tender and fish is flaky.", "Remove from oven. Fluff rice with a fork, stir in the green parts of the onions and remaining lemon juice. Serve immediately."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["lemon (zest and juice)", "garlic, minced", "chicken or vegetable broth", "dried dill or parsley", "Salt and pepper to taste"], "missing_ingredients_count": 5}, "snacks": [{"name": "Greek Yogurt with Berries", "calories": 150}, {"name": "Mixed Nuts", "calories": 200}, {"name": "Apple with Almond Butter", "calories": 150}], "breakfast": {"tags": ["Simple"], "source": "DeepSeek AI", "cook_time": "20 mins", "nutrition": "Calories: 420, Protein: 38g, Carbs: 55g, Fat: 3g", "prep_time": "10 mins", "difficulty": "Easy", "total_time": "30 mins", "ingredients": ["2 white fish fillets (like cod or tilapia, ~6oz each)", "1 cup white rice", "2 green onions, thinly sliced", "1/2 tsp salt", "1/4 tsp black pepper", "1 cup water"], "recipe_name": "Simple Steamed Fish with Scallion Rice", "ai_generated": true, "allergy_safe": true, "instructions": ["Rinse the rice and place it in a pot with 1 cup of water. Bring to a boil, then reduce heat to low, cover, and simmer for 15 minutes.", "While rice cooks, pat fish fillets dry and season both sides with salt and pepper.", "When rice has 8 minutes left, place the fish fillets on top of the rice in the pot. Re-cover and let steam.", "After 8 minutes, check that fish flakes easily with a fork. If not, steam for 1-2 more minutes.", "Fluff the rice and divide between two plates. Top with the steamed fish fillets.", "Garnish generously with sliced green onions and serve immediately."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": [], "missing_ingredients_count": 0}}, "total_calories": 2000, "nutrition_summary": "High protein, moderate carb, rich in omega-3 fatty acids from fish, balanced with whole grains and healthy snacks"}', '2025-12-25T06:25:59.579286+00:00');
INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('730f0c76-b2b1-4b7c-bec5-393a05ba3147', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["Simple", "High-Protein"], "source": "DeepSeek AI", "cook_time": "10 mins", "nutrition": "Calories: ~350, Protein: 14g, Carbs: 50g, Fat: 10g", "prep_time": "10 mins", "difficulty": "Easy", "total_time": "20 mins", "ingredients": ["2 cups cooked rice (preferably day-old)", "2 large eggs, beaten", "2 medium tomatoes, chopped", "1 tbsp cooking oil*", "1 green onion*, sliced (optional)", "Salt* to taste", "1/4 tsp sugar* (optional, to balance tomato acidity)"], "recipe_name": "Simple Tomato & Egg Fried Rice", "ai_generated": true, "allergy_safe": true, "instructions": ["Heat half the oil in a wok or large skillet over medium-high heat. Add the beaten eggs and scramble until just set. Remove and set aside.", "Add the remaining oil to the skillet. Add the chopped tomatoes and cook for 3-4 minutes, mashing slightly with a spatula until they break down and form a saucelike consistency.", "Add the cooked rice to the skillet. Stir-fry for 3-4 minutes, breaking up any clumps, until the rice is heated through and coated with the tomato.", "Return the scrambled eggs to the skillet. Add salt and sugar (if using). Stir-fry for another 1-2 minutes until everything is well combined and hot.", "Garnish with sliced green onion if using. Serve immediately."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["green onion, sliced (optional)", "Salt to taste"], "missing_ingredients_count": 2}, "dinner": {"tags": ["Normal", "High-Protein", "Baked"], "source": "DeepSeek AI", "cook_time": "25 mins", "nutrition": "Calories: ~480, Protein: 38g, Carbs: 55g, Fat: 12g", "prep_time": "15 mins", "difficulty": "Medium", "total_time": "40 mins", "ingredients": ["2 white fish fillets (approx. 150g each)", "1 cup uncooked rice", "2 medium tomatoes, diced", "1 3/4 cups fish or vegetable broth*", "1 tbsp olive oil*", "1 tsp dried oregano*", "1 tsp paprika*", "1 garlic clove*, minced", "Juice of 1/2 lemon*", "Salt* and black pepper* to taste", "Fresh dill* or parsley* for garnish (optional)"], "recipe_name": "Baked Herb-Crusted Fish with Tomato Rice", "ai_generated": true, "allergy_safe": true, "instructions": ["Preheat oven to 200\u00b0C (400\u00b0F).", "In a small bowl, mix olive oil, oregano, paprika, minced garlic, lemon juice, salt, and pepper to form a paste. Coat the fish fillets evenly with this mixture and set aside to marinate for 10 minutes.", "In an oven-safe baking dish, combine the uncooked rice, diced tomatoes, and broth. Season with a pinch of salt and pepper. Stir to combine.", "Place the marinated fish fillets on top of the rice mixture. Cover the dish tightly with foil.", "Bake for 20-25 minutes, or until the rice has absorbed the liquid and the fish flakes easily with a fork.", "Remove from oven and let it rest, covered, for 5 minutes. Fluff the rice with a fork. Garnish with fresh herbs before serving."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["dried oregano", "paprika", "garlic clove, minced", "Juice lemon", "Salt and black pepper to taste", "Fresh dill or parsley for garnish (optional)"], "missing_ingredients_count": 6}, "snacks": [{"name": "Fruit & Nut Mix", "calories": 150}, {"name": "Greek Yogurt", "calories": 100}], "breakfast": {"tags": ["Simple", "High-Protein", "No-Cook"], "source": "DeepSeek AI", "cook_time": "0 mins", "nutrition": "Calories: ~380, Protein: 18g, Carbs: 60g, Fat: 9g", "prep_time": "5 mins", "difficulty": "Easy", "total_time": "5 mins", "ingredients": ["1 large banana, sliced", "1 medium apple, diced", "2 hard-boiled eggs, chopped", "1/2 cup cooked rice, chilled", "1 tsp lemon juice* (optional, to prevent browning)", "Pinch of cinnamon* (optional)"], "recipe_name": "Simple Banana-Apple Protein Bowl", "ai_generated": true, "allergy_safe": true, "instructions": ["If preparing ahead, toss the diced apple in lemon juice to prevent browning.", "In a medium bowl, combine the sliced banana, diced apple, and chopped hard-boiled eggs.", "Add the chilled cooked rice and gently mix all ingredients together.", "Sprinkle with a pinch of cinnamon if desired. Serve immediately as a refreshing, high-protein breakfast or snack."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["lemon juice (optional, to prevent browning)", "cinnamon (optional)"], "missing_ingredients_count": 2}}, "total_calories": 1700, "nutrition_summary": "High protein, moderate carb, balanced omega-3 from fish, includes fruits and vegetables"}', '2025-12-25T08:39:18.358465+00:00');
