INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('edaef045-6977-4dea-9f4c-2002421f09d4', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["Quick", "Savory-Sweet"], "source": "DeepSeek AI", "cook_time": "20m", "nutrition": "400 cal, 22g protein", "prep_time": "10m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["200g Meat, thinly sliced", "1 Apple, sliced", "3 cloves Garlic, sliced", "1 tsp Ginger, grated", "1 tbsp peanut oil", "Salt to taste"], "recipe_name": "Quick Garlic Meat & Apple Saut\u00e9", "ai_generated": true, "allergy_safe": true, "instructions": ["Heat peanut oil in a large pan over medium-high heat.", "Add meat and cook until browned, about 5-7 minutes. Remove from pan.", "In the same pan, add garlic and ginger, saut\u00e9 for 1 minute.", "Add apple slices and cook for 3-4 minutes until tender-crisp.", "Return meat to the pan, stir to combine and heat through. Season with salt. Serve immediately."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Salt to taste"], "missing_ingredients_count": 1}, "dinner": {"tags": ["High-Protein", "Grilled"], "source": "DeepSeek AI", "cook_time": "15m", "nutrition": "380 cal, 30g protein", "prep_time": "15m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["250g Meat, cut into cubes", "2 tbsp crushed Peanuts", "2 cloves Garlic, minced", "1 tsp Ginger, grated", "1 Apple, grated (for marinade)", "Salt to taste"], "recipe_name": "Peanut Garlic Meat Skewers", "ai_generated": true, "allergy_safe": true, "instructions": ["In a bowl, combine meat cubes, minced garlic, grated ginger, grated apple, and salt. Let marinate for 10 minutes.", "Thread meat onto skewers (or cook directly in a pan).", "Cook skewers in a grill pan or oven broiler for 10-12 minutes, turning occasionally, until cooked.", "Sprinkle with crushed peanuts before serving."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Salt to taste"], "missing_ingredients_count": 1}, "breakfast": {"tags": ["Vegetarian", "Light"], "source": "DeepSeek AI", "cook_time": "20m", "nutrition": "320 cal, 5g protein", "prep_time": "10m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["150g Rice, uncooked", "1 Apple, diced", "1 tbsp Ginger, grated", "1 clove Garlic, minced", "1 tsp peanut oil", "Salt to taste"], "recipe_name": "Apple Ginger Rice Bowl", "ai_generated": true, "allergy_safe": true, "instructions": ["Cook rice according to package instructions.", "Heat peanut oil in a small pan over medium heat. Saut\u00e9 garlic and ginger for 1 minute.", "Add diced apple and a pinch of salt. Cook for 3-4 minutes until slightly softened.", "Fluff the cooked rice and gently fold in the apple mixture.", "Serve warm as a light main or side dish."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Salt to taste"], "missing_ingredients_count": 1}}, "nutrition_summary": "Balanced protein, moderate carbs, varied flavors"}', '2026-01-14T04:05:58.929265+00:00');
INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('a919efc8-d96f-4842-a4ad-21dc52815a05', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["No-Cook", "Salad"], "source": "DeepSeek AI", "cook_time": "10m", "nutrition": "290 cal, 28g protein", "prep_time": "20m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["2 cooked chicken breasts, shredded (approx. 300g)", "1 apple, diced", "1 orange, segmented and chopped", "2 tbsp finely chopped peanuts", "3 tbsp milk", "Salt and pepper to taste"], "recipe_name": "Creamy Peanut & Apple Chicken Salad", "ai_generated": true, "allergy_safe": true, "instructions": ["Shred pre-cooked or poached chicken breasts.", "In a bowl, whisk milk with a pinch of salt and pepper to create a light dressing.", "Combine shredded chicken, diced apple, and chopped orange segments in a large bowl.", "Pour the milk dressing over and toss gently to combine.", "Divide between plates and sprinkle with chopped peanuts before serving."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Salt and pepper to taste"], "missing_ingredients_count": 1}, "dinner": {"tags": ["Quick", "One-Pan"], "source": "DeepSeek AI", "cook_time": "15m", "nutrition": "320 cal, 30g protein", "prep_time": "15m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["300g chicken breast, cubed", "1 orange, segmented and juiced", "2 tbsp crushed peanuts", "1 apple, thinly sliced", "1 tbsp oil", "1/4 cup milk (for sauce base)", "1 tsp cornstarch (optional, for thickening)", "Salt to taste"], "recipe_name": "Orange-Peanut Chicken Stir-Fry", "ai_generated": true, "allergy_safe": true, "instructions": ["Heat oil in a wok or large pan over high heat. Stir-fry chicken cubes until browned and cooked through, about 8 minutes.", "Add apple slices and stir-fry for 2 minutes until slightly softened.", "In a small bowl, mix orange juice, milk, and cornstarch (if using). Pour into the pan.", "Cook for 2-3 minutes until sauce thickens slightly. Stir in orange segments.", "Serve immediately, garnished with crushed peanuts."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["cornstarch (optional, for thickening)", "Salt to taste"], "missing_ingredients_count": 2}, "breakfast": {"tags": ["Breakfast", "High-Protein"], "source": "DeepSeek AI", "cook_time": "10m", "nutrition": "310 cal, 25g protein", "prep_time": "20m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["1 cooked chicken breast, sliced (150g)", "1 apple, chopped", "1 orange, peeled", "1/2 cup milk", "2 tbsp crushed peanuts", "Ice (optional)"], "recipe_name": "Apple-Orange Smoothie Bowl with Peanut Chicken", "ai_generated": true, "allergy_safe": true, "instructions": ["For the chicken: Season and pan-sear or grill a chicken breast until cooked. Let rest, then slice.", "For the bowl: In a blender, combine chopped apple, orange, milk, and a few ice cubes. Blend until smooth and thick.", "Pour the smoothie into two bowls.", "Top with sliced chicken breast and sprinkle generously with crushed peanuts."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Ice (optional)"], "missing_ingredients_count": 1}}, "nutrition_summary": "High protein, balanced with fruit and vegetables"}', '2026-01-14T04:57:56.412891+00:00');
INSERT INTO public.saved_meal_plans (plan_id, user_id, plan_data, created_at) VALUES ('b019d819-0989-42e8-b0e1-b37efb13eb56', '7505cf0d-042c-4b15-8e09-213517b326b0', '{"meal_plan": {"lunch": {"tags": ["Quick", "Healthy"], "source": "DeepSeek AI", "cook_time": "20m", "nutrition": "450 cal, 30g protein", "prep_time": "10m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["200g Turkey (diced)", "1 cup Rice", "2 tbsp Soy Sauce", "1 tsp Ginger (grated)", "1 Spring Onion (sliced)", "1/2 Cucumber (sliced)", "1 tsp Chilli (minced)", "1 tsp Spices (e.g., black pepper)", "1 tbsp Water"], "recipe_name": "Soy-Ginger Turkey & Rice Bowl", "ai_generated": true, "allergy_safe": true, "instructions": ["Cook rice according to package instructions.", "In a pan, cook diced turkey until no longer pink. Add soy sauce, ginger, chilli, and spices. Stir-fry for 3-4 minutes, adding a splash of water if needed.", "Serve turkey over rice, garnished with spring onion and fresh cucumber slices."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": [], "missing_ingredients_count": 0}, "dinner": {"tags": ["Healthy", "Baked"], "source": "DeepSeek AI", "cook_time": "15m", "nutrition": "420 cal, 35g protein", "prep_time": "15m", "difficulty": "Easy", "total_time": "30m", "ingredients": ["2 White Fish Fillets (~300g total, from ''Meat'' category)", "1/2 cup Panko", "1 Egg (beaten)", "1/2 Cabbage (shredded)", "1/2 cup Grapes (halved)", "1 Orange (segmented)", "1 tsp Thyme", "1 tsp Spices (salt, pepper, paprika)", "1 tbsp Flour"], "recipe_name": "Panko-Crusted Baked Fish with Grapes & Cabbage", "ai_generated": true, "allergy_safe": true, "instructions": ["Preheat oven to 200\u00b0C (400\u00b0F). Season fish with spices and thyme. Dredge in flour, dip in beaten egg, then coat with panko.", "Place on a baking sheet and bake for 12-15 mins until golden and cooked through.", "Toss shredded cabbage with orange segments and grapes. Serve as a fresh side salad with the crispy fish."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": [], "missing_ingredients_count": 0}, "breakfast": {"tags": ["Breakfast", "Quick"], "source": "DeepSeek AI", "cook_time": "10m", "nutrition": "400 cal, 22g protein", "prep_time": "5m", "difficulty": "Easy", "total_time": "15m", "ingredients": ["4 Eggs", "2 tbsp Heavy Cream", "1 tsp Thyme", "1 Spring Onion (chopped)", "1 tsp Spices (salt, pepper)", "2 slices Bread", "1 tbsp Milk", "1 tbsp Flour", "1/4 tsp Baking Soda", "1/4 tsp Yeast", "Water (as needed)"], "recipe_name": "Creamy Herb Scrambled Eggs with Toast", "ai_generated": true, "allergy_safe": true, "instructions": ["For quick flatbreads: Mix flour, baking soda, yeast, a pinch of salt, milk, and enough water to form a dough. Divide into two, roll out, and cook in a dry pan for 2-3 mins per side. Alternatively, toast bread.", "Whisk eggs with cream, thyme, spring onion, and spices.", "Cook egg mixture in a non-stick pan over low heat, stirring gently until softly set. Serve with the bread or flatbreads."], "similarity_score": 0.95, "dietary_compatible": true, "missing_ingredients": ["Bread"], "missing_ingredients_count": 1}}, "nutrition_summary": "Balanced protein, moderate carbs, includes fish and vegetables"}', '2026-01-14T05:35:35.916742+00:00');

