INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (5, 'Simple Poached Chicken Breast with Ginger & Scallions', '5 mins', '15 mins', '["2 boneless, skinless chicken breasts (about 6 oz each)", "4 cups water", "1-inch piece fresh ginger, sliced", "2 green onions, cut into 2-inch pieces", "1/4 tsp salt", "For serving: low-sodium soy sauce or tamari, sesame seeds, extra sliced green onions"]', 'Place chicken breasts in a medium saucepan. Add water, ginger slices, green onion pieces, and salt. The water should just cover the chicken.
Bring to a gentle simmer over medium heat. Do not boil vigorously.
Once simmering, reduce heat to low, cover, and poach for 12-15 minutes, or until internal temperature reaches 165°F (74°C).
Remove chicken from the liquid and let rest for 5 minutes before shredding or slicing.
Serve shredded chicken over rice or salad. Drizzle with a small amount of low-sodium soy sauce and garnish with sesame seeds and green onions.', '{"fat": "4g", "carbs": "1g", "protein": "36g", "calories": "190"}', '20 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (6, 'Simple Basil-Baked Chicken Breast', '10 mins', '20 mins', '["2 boneless, skinless chicken breasts (about 6 oz each)", "1/4 cup fresh basil leaves, finely chopped", "1 tbsp olive oil", "1/2 tsp salt", "1/4 tsp black pepper", "1 lemon, juiced (optional, for serving)"]', 'Preheat oven to 400°F (200°C).
Pat chicken breasts dry with paper towels. Place them on a baking sheet lined with parchment paper.
In a small bowl, mix the chopped basil, olive oil, salt, and pepper to form a paste.
Rub the basil paste evenly over both sides of each chicken breast.
Bake for 18-22 minutes, or until the internal temperature reaches 165°F (74°C).
Remove from oven, let rest for 5 minutes. Serve with a squeeze of fresh lemon juice if desired.', '{"fat": "13g", "carbs": "1g", "protein": "38g", "calories": "280"}', '30 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (7, 'Lemon-Basil Chicken with Steamed Rice', '15 mins', '20 mins', '["1 large chicken breast (approx. 6 oz / 170g), sliced thinly", "3/4 cup uncooked white rice", "1 1/2 cups water", "1/4 cup fresh basil leaves, thinly sliced", "2 tbsp lemon juice", "1 tsp lemon zest", "1 tbsp olive oil", "1/4 tsp salt", "1/4 tsp black pepper", "1/4 cup low-sodium chicken broth or water (for the pan)"]', 'Cook rice according to package instructions (simmer with water, covered, for 15-18 mins).
While rice cooks, combine lemon juice, lemon zest, salt, and pepper in a bowl. Add the thinly sliced chicken and toss to coat. Let marinate for 10 minutes.
Heat olive oil in a skillet over medium heat. Add the chicken, discarding excess marinade. Cook for 3-4 minutes per side until golden and cooked through.
Add the 1/4 cup of broth or water to the skillet to deglaze, scraping up any browned bits. Let it simmer for 1 minute to create a light sauce.
Remove skillet from heat and stir in the sliced fresh basil.
Serve the lemon-basil chicken and pan juices over a bed of steamed rice.', '{"fat": "11g", "carbs": "55g", "protein": "38g", "calories": "~500"}', '35 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (17, 'Lemon Herb Baked Chicken & Rice', '15 mins', '45 mins', '["4 boneless, skinless chicken breasts (about 1.5 lbs / 680g)", "1 cup long-grain white rice, rinsed", "2 cups low-sodium chicken broth", "1 lemon (zested and juiced)", "3 cloves garlic, minced", "1 tbsp dried oregano", "1 tsp dried thyme", "1 tbsp olive oil", "Salt and black pepper to taste", "Fresh parsley for garnish (optional)"]', 'Preheat oven to 375°F (190°C).
In a small bowl, mix the lemon zest, lemon juice, minced garlic, oregano, thyme, olive oil, salt, and pepper to create a marinade.
Place chicken breasts in a baking dish. Pour half of the marinade over the chicken, ensuring it''s well coated. Set aside for 10 minutes.
In the same baking dish, around the chicken, add the rinsed rice and pour in the chicken broth. Stir the rice gently into the broth.
Pour the remaining marinade over the rice and broth mixture.
Cover the baking dish tightly with aluminum foil.
Bake for 40-45 minutes, or until the chicken is cooked through (internal temperature of 165°F / 74°C) and the rice has absorbed all the liquid.
Remove from oven, let rest covered for 5 minutes. Fluff rice with a fork, garnish with fresh parsley if desired, and serve.', '{"fat": "8g", "carbs": "42g", "protein": "42g", "calories": "420"}', '60 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (14, 'Chicken & Egg Fried ''Rice'' (Cauliflower Base)', '15 mins', '15 mins', '["1 large boneless, skinless chicken breast (6 oz), diced", "2 large eggs, beaten", "4 cups riced cauliflower (fresh or frozen)", "1 tbsp cooking oil (avocado or olive)", "2 tbsp low-sodium soy sauce or tamari (gluten-free)", "1 tsp minced garlic", "1 tsp minced ginger", "2 green onions, sliced", "1/4 tsp white pepper"]', 'Heat 1/2 tbsp oil in a large skillet or wok over medium-high heat. Add the diced chicken and cook until no longer pink, about 5-6 minutes. Remove and set aside.
Add the remaining 1/2 tbsp oil to the skillet. Add the garlic and ginger, stir for 30 seconds until fragrant.
Add the riced cauliflower. Stir-fry for 5-7 minutes until it begins to soften and dry out slightly.
Push the cauliflower to one side of the skillet. Pour the beaten eggs into the empty side and scramble until just set.
Mix the scrambled eggs into the cauliflower. Add the cooked chicken back to the skillet.
Pour the soy sauce over everything and add white pepper. Stir-fry for another 2 minutes until everything is heated through and well combined.
Garnish with sliced green onions and serve immediately.', '{"fat": "17g", "carbs": "18g", "protein": "48g", "calories": "410"}', '30 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (16, 'Lemon-Herb Baked Fish with Steamed Jasmine Rice', '10 mins', '25 mins', '["2 white fish fillets (approx. 6 oz each)", "1 cup jasmine rice", "2 cups water", "1 lemon (juice and zest)", "2 tbsp olive oil", "2 cloves garlic, minced", "1 tsp dried oregano", "1 tsp dried thyme", "Salt and black pepper to taste", "Fresh parsley for garnish (optional)"]', 'Preheat oven to 400°F (200°C).
Rinse the jasmine rice under cold water. In a medium saucepan, combine rice and 2 cups water. Bring to a boil, then reduce heat to low, cover, and simmer for 15-18 minutes until water is absorbed. Remove from heat and let stand, covered, for 5 minutes.
While rice cooks, prepare the fish. Pat fillets dry with a paper towel.
In a small bowl, combine olive oil, lemon juice, lemon zest, minced garlic, oregano, thyme, salt, and pepper.
Place fish fillets in a baking dish. Pour the lemon-herb mixture over the fillets, ensuring they are evenly coated.
Bake for 12-15 minutes, or until the fish flakes easily with a fork.
Fluff the steamed rice with a fork. Serve the baked fish over a bed of rice, spooning any pan juices over the top. Garnish with fresh parsley if desired.', '{"fat": "16g", "carbs": "55g", "protein": "38g", "calories": "520"}', '35 mins', '5790340f-1f13-4c7e-b19d-1289ef039bb6');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (82, 'Quick Ginger-Chilli Wagyu Stir-fry with Rice', '10m', '15m', '["300g Wagyu beef, cut into strips", "1 cup uncooked rice", "2 tbsp ginger, julienned", "2 spring onions, cut into 2-inch pieces", "1 chilli, sliced", "1 tbsp oil", "1/4 cup water or beef broth"]', 'Start cooking rice.
Heat oil in a pan or wok over high heat. Add Wagyu strips and stir-fry for 2 minutes until seared. Remove and set aside.
Add ginger, spring onion, and chilli to the pan. Stir-fry for 1-2 minutes.
Return beef to the pan. Add water or broth and let it simmer for 1-2 minutes to create a light sauce. Serve immediately over the cooked rice.', '{}', '25m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (76, 'Chili-Lime Chicken Skewers', '15m', '15m', '["300g chicken thigh, cut into chunks", "1 fresh chili, deseeded and minced", "2 tbsp lime juice", "1 tbsp olive oil", "1/2 tsp salt", "1/4 tsp paprika", "Wooden skewers (soaked in water)"]', 'In a bowl, mix chicken with chili, lime juice, oil, salt, and paprika. Marinate for 10 minutes.
Thread chicken onto soaked skewers.
Grill or pan-fry skewers over medium-high heat for 12-15 minutes, turning occasionally, until cooked through.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (25, 'Steamed Fish with Chili-Lime Dressing & Rice', '15 mins', '25 mins', '["2 white fish fillets (e.g., cod, tilapia, ~6oz each)", "1 cup uncooked white rice", "2 cups water", "1-2 fresh chili peppers, finely minced", "2 tbsp lime juice (or lemon juice)", "1 tsp grated ginger (optional)", "2 eggs", "Salt to taste", "Fresh cilantro for garnish (optional)"]', 'Rinse the rice until water runs clear. Combine rice and 2 cups water in a pot. Bring to a boil, then reduce heat to low, cover, and simmer for 15-18 minutes. Remove from heat and let sit, covered, for 5 minutes.
While rice cooks, season fish fillets lightly with salt. Place on a heatproof plate that fits inside a steamer or a pot with a steamer basket. Steam over boiling water for 8-10 minutes, or until fish flakes easily with a fork.
In a small bowl, combine minced chili, lime juice, and grated ginger (if using) to make the dressing.
While fish steams, cook eggs to your preference (soft-boiled for 7 minutes or poached).
Fluff the rice with a fork. Serve each portion with a mound of rice, a steamed fish fillet, and a soft-boiled or poached egg on the side.
Drizzle the chili-lime dressing over the fish and rice. Garnish with cilantro if desired.', '{"fat": "12g", "carbs": "55g", "protein": "42g", "calories": "~520"}', '40 mins', 'd37629aa-f5b6-4dda-9c95-ceb3916c3046');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (26, 'Steamed Chili-Lime Fish with Jasmine Rice', '15 mins', '25 mins', '["2 white fish fillets (e.g., cod, tilapia, ~6oz each)", "3/4 cup jasmine rice", "1 1/2 cups water (for rice)", "1 fresh red chili, finely sliced", "1 lime (juice and zest)", "2 cloves garlic, minced", "1 tbsp low-sodium soy sauce", "1 tsp fresh ginger, grated", "1 green onion, sliced", "Salt to taste"]', 'Rinse the jasmine rice until water runs clear. Combine with 1 1/2 cups water and a pinch of salt in a pot. Bring to a boil, then reduce heat to low, cover, and simmer for 15 minutes. Remove from heat and let stand, covered, for 10 minutes.
While rice cooks, pat fish fillets dry. Place each fillet on a large piece of parchment paper or foil.
In a small bowl, mix lime juice, lime zest, soy sauce, minced garlic, and grated ginger. Spoon this mixture evenly over the fish fillets.
Top each fillet with slices of fresh red chili.
Fold the parchment/foil around the fish to create sealed packets. Place packets on a baking sheet.
Steam the fish packets: You can either bake in a preheated oven at 375°F (190°C) for 15-18 minutes, or steam in a steamer basket over boiling water for 12-15 minutes, until fish flakes easily.
Fluff the cooked rice with a fork. Serve the fish over the rice, pouring any juices from the packet over the top. Garnish with sliced green onion.', '{"fat": "4g", "carbs": "52g", "protein": "38g", "calories": "~420"}', '40 mins', 'd37629aa-f5b6-4dda-9c95-ceb3916c3046');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (77, 'Pan-Seared Wagyu with Creamy Milk Sauce', '10m', '20m', '["400g Wagyu beef steak", "200ml milk", "1 tsp salt", "1/2 tsp black pepper", "1/2 tsp garlic powder", "1/2 tsp dried thyme", "1 tbsp cooking oil"]', 'Pat Wagyu steak dry and season generously with salt, pepper, garlic powder, and thyme.
Heat oil in a heavy skillet over medium-high heat. Sear steak for 3-4 minutes per side for medium-rare, or to desired doneness. Remove and let rest.
Reduce heat to low. Pour milk into the skillet, scraping up browned bits. Simmer for 2-3 minutes until slightly thickened. Pour sauce over sliced steak and serve.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (30, 'Baked Herb-Crusted Fish with Ginger Rice Pilaf', '15 mins', '25 mins', '["2 fillets white fish (approx. 6oz/170g each)", "1 cup uncooked white rice", "2 cups water", "1 medium onion, finely chopped", "2 tbsp fresh ginger, minced", "3 tbsp low-sodium soy sauce", "1 tsp dried herbs (e.g., thyme, oregano, or dill)", "1 egg white, lightly beaten", "Black pepper to taste", "Lemon wedge for serving (optional)"]', 'Preheat oven to 400°F (200°C). Line a baking sheet with parchment paper.
Pat fish fillets dry. Brush lightly with beaten egg white. Sprinkle evenly with dried herbs and black pepper. Place on prepared baking sheet.
Bake fish for 12-15 minutes, or until opaque and flaky.
While fish bakes, prepare rice pilaf. In a saucepan, sauté chopped onion and minced ginger over medium heat until soft (add a splash of water if sticking).
Add uncooked rice and stir for 1 minute. Add 2 cups water and 2 tbsp soy sauce. Bring to a boil.
Reduce heat to low, cover, and simmer for 15-18 minutes, until rice is tender and liquid is absorbed. Fluff with a fork.
Serve baked fish over a bed of ginger rice pilaf. Drizzle with remaining 1 tbsp soy sauce. Serve with a lemon wedge if desired.', '{"fat": "2g", "carbs": "60g", "protein": "38g", "calories": "~420"}', '40 mins', 'c184ea32-e082-4c03-80ea-b69911f24033');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (31, 'Steamed Ginger-Soy Fish with Scrambled Eggs', '10 mins', '15 mins', '["2 fillets white fish (e.g., cod, tilapia) (approx. 6oz/170g each)", "4 large eggs", "1/2 medium onion, thinly sliced", "1 tbsp fresh ginger, julienned", "2 tbsp low-sodium soy sauce", "1 tbsp water", "1 tsp grated ginger", "Salt and pepper to taste", "Optional garnish: sliced green onion tops"]', 'Pat fish fillets dry and place on a heatproof plate that will fit inside your steamer.
Scatter the sliced onion and julienned ginger over the fish.
In a small bowl, mix 1 tbsp soy sauce with 1 tbsp water. Pour this mixture over the fish.
Bring water in a steamer to a boil. Place the plate with fish in the steamer, cover, and steam for 8-10 minutes, or until fish flakes easily.
While fish steams, whisk eggs with 1 tsp grated ginger, 1 tbsp soy sauce, and a pinch of pepper.
Heat a non-stick skillet over medium-low heat. Pour in egg mixture and cook, gently stirring, until soft curds form and eggs are just set.
Serve steamed fish alongside the ginger-scrambled eggs. Spoon any steaming juices from the fish plate over the top.', '{"fat": "12g (primarily from egg yolks)", "carbs": "5g", "protein": "42g", "calories": "~320"}', '25 mins', 'c184ea32-e082-4c03-80ea-b69911f24033');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (33, 'Chili Chicken & Egg Fried Rice', '15 mins', '20 mins', '["2 cups cooked white rice (preferably day-old)", "1 large chicken breast (approx. 200g), diced", "2 large eggs, beaten", "1-2 fresh red or green chilies, finely chopped (adjust to heat preference)", "2 cloves garlic, minced", "1 tbsp low-sodium soy sauce", "1 tsp sesame oil (optional, for flavor)", "1 tbsp cooking oil (like canola or avocado)", "2 green onions, sliced", "Salt and pepper to taste"]', 'Heat 1/2 tbsp oil in a large wok or skillet over medium-high heat. Add diced chicken, season with salt and pepper, and cook until no longer pink (5-7 mins). Remove and set aside.
Add remaining 1/2 tbsp oil to the wok. Add beaten eggs and scramble until just set. Remove and set aside with the chicken.
Add the minced garlic and chopped chili to the wok. Stir-fry for 30 seconds until fragrant.
Increase heat to high. Add the cooked rice, breaking up any clumps. Stir-fry for 2-3 minutes until heated through.
Return the cooked chicken and scrambled eggs to the wok. Add soy sauce and sesame oil (if using). Toss everything together until well combined and hot.
Remove from heat, stir in sliced green onions, and serve immediately.', '{"fat": "12g", "carbs": "45g", "protein": "38g", "calories": "~450"}', '35 mins', 'd37629aa-f5b6-4dda-9c95-ceb3916c3046');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (40, 'Low-Carb Chicken & Egg Fried Cauliflower Rice', '15 mins', '15 mins', '["1 medium head cauliflower, grated or processed into rice-sized pieces (about 4 cups)", "2 large eggs, beaten", "1 boneless, skinless chicken breast (about 6 oz), diced into small cubes", "2 tbsp cooking oil (like avocado or olive oil), divided", "2 cloves garlic, minced", "1 tbsp fresh ginger, grated", "2 tbsp low-sodium soy sauce or tamari", "1 tsp sesame oil", "2 green onions, sliced", "Salt and pepper to taste"]', 'Grate the cauliflower using a box grater or pulse in a food processor until it resembles rice. Set aside.
Season the diced chicken with salt and pepper. Heat 1 tbsp of oil in a large wok or skillet over medium-high heat. Add the chicken and cook for 4-5 minutes until cooked through and lightly browned. Remove and set aside.
Add the remaining 1 tbsp oil to the pan. Add the garlic and ginger, stir-fry for 30 seconds until fragrant.
Push the aromatics to the side. Pour the beaten eggs into the empty space and scramble until just set.
Add the cauliflower ''rice'' to the pan. Stir-fry for 5-7 minutes until it softens and begins to get slightly crispy.
Return the cooked chicken to the pan. Add the soy sauce and sesame oil. Stir everything together and cook for another 2 minutes to heat through.
Remove from heat, stir in the green onions, and serve immediately.', '{"fat": "16g (per serving", "carbs": "12g", "protein": "32g", "calories": "320"}', '30 mins', '87215699-8e79-4000-bc47-19e746f4a598');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (78, 'Red Wine Glazed Pork & Scrambled Eggs', '10m', '20m', '["250g pork belly, diced", "1 cup uncooked rice", "3 eggs", "2 tbsp soy sauce", "3 tbsp red wine"]', 'Start cooking rice.
In a non-stick skillet, cook diced pork belly over medium heat until browned and fat renders, about 10 minutes. Remove pork, set aside, leaving 1 tbsp fat in pan.
Whisk eggs with 1 tbsp soy sauce. Pour into the skillet and scramble until just set. Remove and set aside.
Return pork to skillet. Add remaining 1 tbsp soy sauce and red wine. Cook over medium-high heat, stirring, until liquid reduces to a glossy glaze, about 3-4 minutes.
Fold scrambled eggs back into the skillet to combine gently. Serve immediately over cooked rice.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (44, 'High-Protein Chicken & Egg Fried Rice', '15 mins', '20 mins', '["1 cup uncooked white rice", "6 chicken wings, deboned and meat diced", "3 large eggs, beaten", "2 tbsp cooking oil (e.g., vegetable or sesame)", "2 cloves garlic, minced", "1 tbsp soy sauce (or tamari)", "1 tsp grated ginger", "2 green onions, sliced", "Salt and pepper to taste"]', 'Cook 1 cup of rice according to package instructions. Spread on a tray to cool slightly.
While rice cooks, debone chicken wings: cut through the skin and tendons at both ends of each wing segment, push the meat down to one end, and cut off the bone. Dice the meat into small pieces.
Heat 1 tbsp oil in a large wok or skillet over medium-high heat. Add diced chicken, season with salt and pepper, and cook until golden and cooked through, about 5-7 minutes. Remove and set aside.
Add remaining 1 tbsp oil to the wok. Pour in beaten eggs and scramble until just set. Break into small pieces with a spatula. Remove and set aside with the chicken.
Add minced garlic and ginger to the wok; stir for 30 seconds until fragrant. Add the cooled rice, breaking up any clumps. Stir-fry for 3-4 minutes.
Return chicken and scrambled eggs to the wok. Add soy sauce and stir-fry for another 2-3 minutes until everything is heated through and well combined.
Remove from heat, stir in sliced green onions, and serve immediately.', '{"fat": "18g (per serving", "carbs": "48g", "protein": "38g", "calories": "520"}', '35 mins', 'd37629aa-f5b6-4dda-9c95-ceb3916c3046');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (79, 'Quick Wagyu Sliders with Cabbage Slaw', '15m', '15m', '["200g Wagyu beef, minced", "1 cup flour", "1 tsp yeast", "1/2 cup warm water", "1/4 tsp baking soda", "1/4 head cabbage, finely shredded", "2 tbsp milk", "1 egg", "Pinch of salt"]', 'Mix flour, yeast, baking soda, and salt. Add warm water to form a sticky dough. Let rest 10 mins. Divide into 4 small buns, shape, and bake in a preheated oven at 220°C for 12 mins.
Mix cabbage with milk and a pinch of salt for a quick slaw.
Form Wagyu into 2 small patties. Cook in a hot pan for 3-4 mins per side. Assemble sliders with patty and cabbage slaw.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (54, '🍳 Breakfast: Simple Steamed Fish with Scallion Rice', '10 mins', '20 mins', '["2 white fish fillets (like cod or tilapia, ~6oz each)", "1 cup white rice", "2 green onions, thinly sliced", "1/2 tsp salt", "1/4 tsp black pepper", "1 cup water"]', 'Rinse the rice and place it in a pot with 1 cup of water. Bring to a boil, then reduce heat to low, cover, and simmer for 15 minutes.
While rice cooks, pat fish fillets dry and season both sides with salt and pepper.
When rice has 8 minutes left, place the fish fillets on top of the rice in the pot. Re-cover and let steam.
After 8 minutes, check that fish flakes easily with a fork. If not, steam for 1-2 more minutes.
Fluff the rice and divide between two plates. Top with the steamed fish fillets.
Garnish generously with sliced green onions and serve immediately.', '{"fat": "3g", "carbs": "55g", "protein": "38g", "calories": "420"}', '30 mins', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (56, 'Chili Fish & Egg Fried Rice', '10m', '20m', '["fish (white, cubed)", "Rice (cooked, day-old)", "Egg (2)", "chili (1, finely chopped)", "cooking oil", "salt", "pepper"]', 'Heat oil in a wok or large pan. Scramble the eggs, then set aside.
In the same pan, cook the fish cubes until opaque and flaky. Season with salt and pepper. Remove and set aside.
Add a bit more oil, stir-fry the chopped chili briefly. Add the cooked rice, breaking up clumps. Return eggs and fish to the pan. Toss everything together until heated through. Adjust seasoning and serve.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (58, '🍳 Breakfast: Banana Apple Ginger Scramble', '5m', '10m', '["egg", "banana", "apple", "ginger"]', 'Whisk 2-3 eggs in a bowl. Dice apple and banana, grate a small piece of ginger.
Sauté apple and ginger in a non-stick pan until slightly soft. Pour in eggs and scramble gently.
When eggs are nearly set, add banana slices and fold gently. Cook for 1 more minute and serve.', '{}', '15m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (60, '🍳 Breakfast: Banana Egg Rice Scramble', '5m', '15m', '["2 cups cooked rice", "3 eggs", "1 banana, sliced", "1 tsp oil", "Pinch of salt"]', 'Heat oil in a non-stick pan over medium heat.
Add cooked rice and stir for 2-3 mins to warm.
Push rice to one side. Crack eggs into the pan and scramble until nearly set.
Mix eggs with rice. Add banana slices and gently stir for 1 min to warm. Season with a pinch of salt.', '{}', '20m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (62, 'Quick Ginger Chicken Egg Scramble with Rice', '5m', '15m', '["1.5 cups cooked rice", "200g chicken breast, cut into small cubes", "3 eggs", "3 spring onions, finely chopped", "1 tbsp fresh ginger, minced", "1 tbsp oil", "Salt and pepper to taste"]', 'Heat oil in a large non-stick pan over medium heat. Add chicken, ginger, and half of the spring onions. Season with salt and pepper. Cook for 6-8 minutes until chicken is fully cooked.
In a bowl, beat the eggs with a pinch of salt.
Push the cooked chicken to the edges of the pan, creating a well in the center. Pour the beaten eggs into the center and scramble gently.
Once eggs are nearly set, mix them with the chicken in the pan.
Add the cooked rice to the pan. Stir everything together and cook for 2-3 minutes until the rice is hot.
Remove from heat, stir in the remaining spring onions, and serve immediately.', '{}', '20m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (63, 'Ginger Chicken Egg Scramble', '10m', '15m', '["200g chicken breast, diced", "1 tbsp fresh ginger, grated", "1 medium carrot, grated", "2 large eggs", "1 tbsp cooking oil", "Salt and pepper to taste"]', 'Heat oil in a pan over medium heat. Add diced chicken and cook until no longer pink.
Add grated ginger and carrot to the pan. Stir-fry for 3-4 minutes until carrots soften.
Beat eggs in a bowl, then pour over the chicken and vegetable mixture. Stir gently until eggs are fully cooked. Season with salt and pepper.', '{}', '25m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (64, '🥗 Lunch: Scrambled Egg & Apple Chicken Stir-fry', '10m', '15m', '["150g chicken breast, thinly sliced", "3 eggs", "1 apple, cored and thinly sliced", "1 carrot, thinly sliced", "2 spring onions, sliced", "1 tsp ginger, minced", "1 tsp oil", "salt and pepper to taste"]', 'Heat oil in a large pan or wok. Sauté ginger until fragrant. Add chicken and cook until browned and cooked through. Remove and set aside.
In the same pan, add carrot slices and stir-fry for 2-3 minutes until slightly tender.
Push vegetables to the side. Pour beaten eggs into the pan and scramble until softly set.
Return chicken to the pan. Add apple slices and most of the spring onions. Stir-fry for 1-2 minutes until everything is heated through.
Season with salt and pepper. Garnish with remaining spring onions and serve immediately.', '{}', '25m', '7505cf0d-042c-4b15-8e09-213517b326b0');
INSERT INTO public.recipes (recipe_id, name, prep_time, cook_time, ingredients_json, directions, nutrition_facts, total_time, user_id) VALUES (67, 'Tomato Potato Rice Bowl', '10m', '20m', '["1 cup white rice", "2 medium potatoes, diced", "2 large tomatoes, chopped", "1 tbsp oil", "Salt and pepper to taste", "1/2 tsp paprika (optional)"]', 'Rinse rice and cook according to package instructions.
Heat oil in a pan. Add diced potatoes and cook for 10-12 minutes until tender.
Add chopped tomatoes, salt, pepper, and paprika. Cook for 5-7 minutes until tomatoes soften.
Serve the tomato-potato mixture over the cooked rice.', '{}', '30m', '7505cf0d-042c-4b15-8e09-213517b326b0');

